from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

@app.route('/weather')
def weather():
    # Extract location from query parameters for dynamic API calls
    location = request.args.get('location')
    params = {'q': location}

    # Use requests library to fetch weather data from OpenWeatherMap API
    resp = requests.get('https://api.openweathermap.org/data/2.5/weather', params=params)
    return resp.text

if __name__ == '__main__':
    app.run()

from flask import Flask, request, render_template
import pandas as pd

app = Flask(__name__)

# Standard Flask route structure to handle HTTP GET requests for home page
@app.route('/')
def index():
    # Use render_template() for dynamic content delivery to display main page
    return render_template('index.html')

# POST endpoint specifically designed to handle form data submissions
@app.route('/getfavorite', methods=['POST'])
def get_favorite():
    # Extract user input from the HTML form using request.form
    color = request.form['color']
    season = request.form['season']

    # Organize form data into a Python dictionary for easy management
    favorite_dict = {"color": color, "season": season}
    # Convert dictionary to pandas DataFrame for potential data analysis or manipulation
    fave_df = pd.DataFrame.from_dict(favorite_dict, orient='index')

    # Return DataFrame in dictionary format back to user to provide immediate visual confirmation
    return fave_df.to_dict()

